function resolveHostExperienceShadowOptions(value: unknown): HostExperienceShadowOptions | undefined {
  if (!isRecord(value) || value.enabled !== true) return undefined;
  return {
    workspaceRoot: resolveHostSekbWorkspaceRoot(),
    enabled: true,
    dualWrite: true,
  };
}

