};

type InjectionRow = {
  id: string;
  role_name: string;
  task: string | null;
  session_key: string | null;
  card_ids_json: string;
  reasons_json: string;
  budget_json: string;
  estimated_tokens_json: string;
  truncated: number;
  policy_version: string | null;
  selector_snapshot_json: string | null;
